import axios from "axios";

const API = axios.create({
  baseURL: "http://localhost:8000",
  withCredentials: true, // Ensure cookies (refresh token) are sent
});

// Function to get access token from local storage
const getAccessToken = () => {
  const token = localStorage.getItem("accessToken");
  console.log("📢 Access Token:", token); // ✅ Debug ke liye token ko console karo
  return token || null;
};


// Request Interceptor: Attach Access Token
API.interceptors.response.use(
  (response) => response,
  async (error) => {
    const originalRequest = error.config;
    
    if (error.response?.status === 403 && !originalRequest._retry) {
      originalRequest._retry = true;
      try {
        console.log("🔄 Refreshing Token...");
        const { data } = await axios.post(
          "http://localhost:8000/api/auth/refresh", // ✅ Base URL already hai to full path likho
          {},
          { withCredentials: true }
        );

        // ✅ New Token ko Local Storage me set karo
        localStorage.setItem("accessToken", data.accessToken);

        // ✅ Authorization Header ko update karo
        originalRequest.headers.Authorization = `Bearer ${data.accessToken}`;

        console.log("✅ Token refreshed:", data.accessToken);
        return API(originalRequest); // ✅ Retry original request
      } catch (refreshError) {
        console.error("❌ Refresh Token Failed. Logging out.");
        localStorage.removeItem("accessToken");
        window.location.href = "/login"; // ✅ Login page pe redirect karo
      }
    }
    
    return Promise.reject(error);
  }
);


// Response Interceptor: Handle Expired Token & Refresh
API.interceptors.response.use(
  (response) => response,
  async (error) => {
    const originalRequest = error.config;
    if (error.response?.status === 403 && !originalRequest._retry) {
      originalRequest._retry = true;
      try {
        const { data } = await axios.post(
          "http://localhost:8000/api/auth/refresh",
          {},
          { withCredentials: true }
        );
        localStorage.setItem("accessToken", data.accessToken);
        originalRequest.headers.Authorization = `Bearer ${data.accessToken}`;
        return API(originalRequest); // Retry failed request
      } catch (refreshError) {
        console.error("Refresh Token Expired. Logging out.");
        localStorage.removeItem("accessToken");
        window.location.href = "/login"; // Redirect to login
      }
    }
    return Promise.reject(error);
  }
);

export default API;
